package com.cybershield.controller;
import com.cybershield.dto.*; import com.cybershield.model.*; import com.cybershield.repository.*; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.security.access.AccessDeniedException; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/incidents") public class IncidentController { final IncidentRepository repo;final UserRepository users;final ActivityLogRepository logs; final CommentRepository comments; public IncidentController(IncidentRepository r,UserRepository u,ActivityLogRepository l,CommentRepository c){repo=r;users=u;logs=l;comments=c;} User current(Authentication a){return users.findByEmail(a.getName()).orElseThrow();} boolean canRead(Incident i,User u){return u.getRole()==Role.ADMIN||i.getReporter().getId().equals(u.getId())||(i.getAssignee()!=null&&i.getAssignee().getId().equals(u.getId()));} Incident readable(Long id,Authentication a){Incident i=repo.findById(id).orElseThrow();if(!canRead(i,current(a)))throw new AccessDeniedException("Incident access denied");return i;} void log(User u,String action,Long id,String d){ActivityLog l=new ActivityLog();l.setUser(u);l.setAction(action);l.setEntityType("INCIDENT");l.setEntityId(id);l.setDetails(d);logs.save(l);} @GetMapping List<Incident> all(Authentication a){User u=current(a);return repo.findAll().stream().filter(i->canRead(i,u)).sorted(Comparator.comparing(Incident::getCreatedAt).reversed()).toList();} @GetMapping("/{id}") Incident one(@PathVariable Long id,Authentication a){return readable(id,a);} @PostMapping Incident create(@Valid @RequestBody IncidentRequest r,Authentication a){User u=current(a);Incident i=new Incident();i.setTitle(r.title());i.setIncidentType(r.incidentType());i.setSeverity(r.severity());i.setPriority(r.priority());i.setStatus(r.status()==null||r.status().isBlank()?"OPEN":r.status());i.setAffectedSystem(r.affectedSystem());i.setAffectedUsers(r.affectedUsers());i.setDescription(r.description());i.setDetectedAt(r.detectedAt()==null||r.detectedAt().isBlank()?LocalDateTime.now():LocalDateTime.parse(r.detectedAt()));i.setReporter(u);if(r.assigneeId()!=null)i.setAssignee(users.findById(r.assigneeId()).orElse(null));Incident s=repo.save(i);log(u,"INCIDENT_CREATED",s.getId(),s.getTitle());return s;} @PutMapping("/{id}") Incident update(@PathVariable Long id,@Valid @RequestBody IncidentRequest r,Authentication a){Incident i=readable(id,a);User actor=current(a);if(actor.getRole()==Role.USER)throw new AccessDeniedException("Only staff may update incidents");if(actor.getRole()==Role.ANALYST&&(i.getAssignee()==null||!i.getAssignee().getId().equals(actor.getId())))throw new AccessDeniedException("Incident assignment required");i.setTitle(r.title());i.setIncidentType(r.incidentType());i.setSeverity(r.severity());i.setPriority(r.priority());if(r.status()!=null&&!r.status().isBlank())i.setStatus(r.status());i.setAffectedSystem(r.affectedSystem());i.setAffectedUsers(r.affectedUsers());i.setDescription(r.description());if(r.assigneeId()!=null)i.setAssignee(users.findById(r.assigneeId()).orElse(null));if("RESOLVED".equals(i.getStatus())&&i.getResolvedAt()==null)i.setResolvedAt(LocalDateTime.now());if(!"RESOLVED".equals(i.getStatus()))i.setResolvedAt(null);Incident s=repo.save(i);log(current(a),"INCIDENT_UPDATED",id,s.getStatus());return s;} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") void delete(@PathVariable Long id,Authentication a){repo.deleteById(id);log(current(a),"INCIDENT_DELETED",id,"Deleted incident");} @GetMapping("/{id}/comments") List<IncidentComment> comments(@PathVariable Long id,Authentication a){readable(id,a);return comments.findByIncidentIdOrderByCreatedAtAsc(id);} @PostMapping("/{id}/comments") IncidentComment comment(@PathVariable Long id,@RequestBody Map<String,String> body,Authentication a){IncidentComment c=new IncidentComment();c.setIncident(readable(id,a));c.setAuthor(current(a));String value=body.getOrDefault("comment","").trim();if(value.isEmpty()||value.length()>5000)throw new IllegalArgumentException("Comment must contain 1 to 5000 characters");c.setComment(value);return comments.save(c);} }
